#include <immintrin.h>
#include <stdint.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

/* ChaCha20 4-block AVX2, RFC 7539. out and in may alias. */
static inline __m256i rotl32_avx(__m256i x, int n) {
    return _mm256_or_si256(_mm256_slli_epi32(x, n), _mm256_srli_epi32(x, 32 - n));
}

static void chacha20_xor_avx2(uint8_t *out, const uint8_t *in, size_t len,
                              const uint8_t key[32], const uint8_t nonce[12], uint32_t counter) {
    uint32_t k[8];
    memcpy(k, key, 32);
    uint32_t n[3];
    memcpy(n, nonce, 12);

    const __m256i rot8 = _mm256_set_epi8(
        14, 13, 12, 15, 10, 9, 8, 11, 6, 5, 4, 7, 2, 1, 0, 3,
        14, 13, 12, 15, 10, 9, 8, 11, 6, 5, 4, 7, 2, 1, 0, 3);
    const __m256i rot16 = _mm256_set_epi8(
        13, 12, 15, 14, 9, 8, 11, 10, 5, 4, 7, 6, 1, 0, 3, 2,
        13, 12, 15, 14, 9, 8, 11, 10, 5, 4, 7, 6, 1, 0, 3, 2);

    /* state rows across 4 blocks in lanes 0..3 and 4..7 (two copies? we'll do 8 blocks = 512 bytes) */
    /* 8-way: each ymm holds one state word for 8 consecutive blocks */
    size_t off = 0;
    while (off + 512 <= len) {
        uint32_t ctr = counter + (uint32_t)(off / 64);
        __m256i x0 = _mm256_set1_epi32(0x61707865);
        __m256i x1 = _mm256_set1_epi32(0x3320646e);
        __m256i x2 = _mm256_set1_epi32(0x79622d32);
        __m256i x3 = _mm256_set1_epi32(0x6b206574);
        __m256i x4 = _mm256_set1_epi32(k[0]);
        __m256i x5 = _mm256_set1_epi32(k[1]);
        __m256i x6 = _mm256_set1_epi32(k[2]);
        __m256i x7 = _mm256_set1_epi32(k[3]);
        __m256i x8 = _mm256_set1_epi32(k[4]);
        __m256i x9 = _mm256_set1_epi32(k[5]);
        __m256i x10 = _mm256_set1_epi32(k[6]);
        __m256i x11 = _mm256_set1_epi32(k[7]);
        __m256i x12 = _mm256_set_epi32(ctr+7, ctr+6, ctr+5, ctr+4, ctr+3, ctr+2, ctr+1, ctr);
        __m256i x13 = _mm256_set1_epi32(n[0]);
        __m256i x14 = _mm256_set1_epi32(n[1]);
        __m256i x15 = _mm256_set1_epi32(n[2]);

        __m256i s0=x0,s1=x1,s2=x2,s3=x3,s4=x4,s5=x5,s6=x6,s7=x7;
        __m256i s8=x8,s9=x9,s10=x10,s11=x11,s12=x12,s13=x13,s14=x14,s15=x15;

        for (int i = 0; i < 10; i++) {
            /* column rounds */
            s0 = _mm256_add_epi32(s0, s4); s12 = _mm256_xor_si256(s12, s0); s12 = rotl32_avx(s12, 16);
            s8 = _mm256_add_epi32(s8, s12); s4 = _mm256_xor_si256(s4, s8); s4 = rotl32_avx(s4, 12);
            s0 = _mm256_add_epi32(s0, s4); s12 = _mm256_xor_si256(s12, s0); s12 = _mm256_shuffle_epi8(s12, rot8);
            s8 = _mm256_add_epi32(s8, s12); s4 = _mm256_xor_si256(s4, s8); s4 = rotl32_avx(s4, 7);

            s1 = _mm256_add_epi32(s1, s5); s13 = _mm256_xor_si256(s13, s1); s13 = rotl32_avx(s13, 16);
            s9 = _mm256_add_epi32(s9, s13); s5 = _mm256_xor_si256(s5, s9); s5 = rotl32_avx(s5, 12);
            s1 = _mm256_add_epi32(s1, s5); s13 = _mm256_xor_si256(s13, s1); s13 = _mm256_shuffle_epi8(s13, rot8);
            s9 = _mm256_add_epi32(s9, s13); s5 = _mm256_xor_si256(s5, s9); s5 = rotl32_avx(s5, 7);

            s2 = _mm256_add_epi32(s2, s6); s14 = _mm256_xor_si256(s14, s2); s14 = rotl32_avx(s14, 16);
            s10 = _mm256_add_epi32(s10, s14); s6 = _mm256_xor_si256(s6, s10); s6 = rotl32_avx(s6, 12);
            s2 = _mm256_add_epi32(s2, s6); s14 = _mm256_xor_si256(s14, s2); s14 = _mm256_shuffle_epi8(s14, rot8);
            s10 = _mm256_add_epi32(s10, s14); s6 = _mm256_xor_si256(s6, s10); s6 = rotl32_avx(s6, 7);

            s3 = _mm256_add_epi32(s3, s7); s15 = _mm256_xor_si256(s15, s3); s15 = rotl32_avx(s15, 16);
            s11 = _mm256_add_epi32(s11, s15); s7 = _mm256_xor_si256(s7, s11); s7 = rotl32_avx(s7, 12);
            s3 = _mm256_add_epi32(s3, s7); s15 = _mm256_xor_si256(s15, s3); s15 = _mm256_shuffle_epi8(s15, rot8);
            s11 = _mm256_add_epi32(s11, s15); s7 = _mm256_xor_si256(s7, s11); s7 = rotl32_avx(s7, 7);

            /* diagonal rounds: rotate words 4,8,12 lanes within each "column group" 
               For 8 independent blocks, diagonal is just a word-index rotation, NOT a lane shuffle.
               Each lane is an independent block, so diagonal round is:
               s0+=s5; s15^=s0; ... standard word permutation, no lane permute. */
            s0 = _mm256_add_epi32(s0, s5); s15 = _mm256_xor_si256(s15, s0); s15 = rotl32_avx(s15, 16);
            s10 = _mm256_add_epi32(s10, s15); s5 = _mm256_xor_si256(s5, s10); s5 = rotl32_avx(s5, 12);
            s0 = _mm256_add_epi32(s0, s5); s15 = _mm256_xor_si256(s15, s0); s15 = _mm256_shuffle_epi8(s15, rot8);
            s10 = _mm256_add_epi32(s10, s15); s5 = _mm256_xor_si256(s5, s10); s5 = rotl32_avx(s5, 7);

            s1 = _mm256_add_epi32(s1, s6); s12 = _mm256_xor_si256(s12, s1); s12 = rotl32_avx(s12, 16);
            s11 = _mm256_add_epi32(s11, s12); s6 = _mm256_xor_si256(s6, s11); s6 = rotl32_avx(s6, 12);
            s1 = _mm256_add_epi32(s1, s6); s12 = _mm256_xor_si256(s12, s1); s12 = _mm256_shuffle_epi8(s12, rot8);
            s11 = _mm256_add_epi32(s11, s12); s6 = _mm256_xor_si256(s6, s11); s6 = rotl32_avx(s6, 7);

            s2 = _mm256_add_epi32(s2, s7); s13 = _mm256_xor_si256(s13, s2); s13 = rotl32_avx(s13, 16);
            s8 = _mm256_add_epi32(s8, s13); s7 = _mm256_xor_si256(s7, s8); s7 = rotl32_avx(s7, 12);
            s2 = _mm256_add_epi32(s2, s7); s13 = _mm256_xor_si256(s13, s2); s13 = _mm256_shuffle_epi8(s13, rot8);
            s8 = _mm256_add_epi32(s8, s13); s7 = _mm256_xor_si256(s7, s8); s7 = rotl32_avx(s7, 7);

            s3 = _mm256_add_epi32(s3, s4); s14 = _mm256_xor_si256(s14, s3); s14 = rotl32_avx(s14, 16);
            s9 = _mm256_add_epi32(s9, s14); s4 = _mm256_xor_si256(s4, s9); s4 = rotl32_avx(s4, 12);
            s3 = _mm256_add_epi32(s3, s4); s14 = _mm256_xor_si256(s14, s3); s14 = _mm256_shuffle_epi8(s14, rot8);
            s9 = _mm256_add_epi32(s9, s14); s4 = _mm256_xor_si256(s4, s9); s4 = rotl32_avx(s4, 7);
        }

        s0 = _mm256_add_epi32(s0, x0);
        s1 = _mm256_add_epi32(s1, x1);
        s2 = _mm256_add_epi32(s2, x2);
        s3 = _mm256_add_epi32(s3, x3);
        s4 = _mm256_add_epi32(s4, x4);
        s5 = _mm256_add_epi32(s5, x5);
        s6 = _mm256_add_epi32(s6, x6);
        s7 = _mm256_add_epi32(s7, x7);
        s8 = _mm256_add_epi32(s8, x8);
        s9 = _mm256_add_epi32(s9, x9);
        s10 = _mm256_add_epi32(s10, x10);
        s11 = _mm256_add_epi32(s11, x11);
        s12 = _mm256_add_epi32(s12, x12);
        s13 = _mm256_add_epi32(s13, x13);
        s14 = _mm256_add_epi32(s14, x14);
        s15 = _mm256_add_epi32(s15, x15);

        /* transpose 8 blocks of 16 words into sequential output.
           Each block b's word w is lane b of s[w].
           We'll extract lane by lane. */
        uint32_t words[16][8];
        _mm256_storeu_si256((__m256i*)words[0], s0);
        _mm256_storeu_si256((__m256i*)words[1], s1);
        _mm256_storeu_si256((__m256i*)words[2], s2);
        _mm256_storeu_si256((__m256i*)words[3], s3);
        _mm256_storeu_si256((__m256i*)words[4], s4);
        _mm256_storeu_si256((__m256i*)words[5], s5);
        _mm256_storeu_si256((__m256i*)words[6], s6);
        _mm256_storeu_si256((__m256i*)words[7], s7);
        _mm256_storeu_si256((__m256i*)words[8], s8);
        _mm256_storeu_si256((__m256i*)words[9], s9);
        _mm256_storeu_si256((__m256i*)words[10], s10);
        _mm256_storeu_si256((__m256i*)words[11], s11);
        _mm256_storeu_si256((__m256i*)words[12], s12);
        _mm256_storeu_si256((__m256i*)words[13], s13);
        _mm256_storeu_si256((__m256i*)words[14], s14);
        _mm256_storeu_si256((__m256i*)words[15], s15);

        uint8_t *o = out + off;
        const uint8_t *inp = in + off;
        for (int b = 0; b < 8; b++) {
            uint32_t blk[16];
            for (int w = 0; w < 16; w++) blk[w] = words[w][b];
            uint8_t *dst = o + b * 64;
            const uint8_t *src = inp + b * 64;
            /* xor 64 bytes */
            uint8_t tmp[64];
            memcpy(tmp, blk, 64);
            for (int i = 0; i < 64; i++) dst[i] = tmp[i] ^ src[i];
        }
        off += 512;
    }
    /* tail: scalar fallback omitted for bench of aligned size */
    (void)off;
}

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

int main() {
    size_t n = 40000 * 1024;
    n = n - (n % 512);
    uint8_t *buf = aligned_alloc(64, n);
    memset(buf, 1, n);
    uint8_t key[32] = {0};
    uint8_t nonce[12] = {0};
    for (int i = 0; i < 32; i++) key[i] = i;
    /* warmup */
    chacha20_xor_avx2(buf, buf, n, key, nonce, 1);
    double t0 = now();
    int iters = 5;
    for (int i = 0; i < iters; i++)
        chacha20_xor_avx2(buf, buf, n, key, nonce, 1);
    double dt = now() - t0;
    printf("avx2 chacha %.3f ms/iter  %.2f GB/s\n", dt/iters*1000, n/(dt/iters)/1e9);
    /* checksum */
    uint64_t s = 0;
    for (size_t i = 0; i < 64; i++) s += buf[i];
    printf("sum %llu\n", (unsigned long long)s);
    return 0;
}
EOF
