    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

int main() {
    size_t n = 40000ull * 1024;
    uint8_t *pt = malloc(n);
    uint8_t *ct = malloc(n);
    memset(pt, 1, n);
    uint8_t key[32];
    uint8_t nonce[12];
    memset(key, 2, 32);
    memset(nonce, 3, 12);
    uint8_t aad[32];
    memset(aad, 4, 32);
    uint8_t tag[16];

    struct chacha_poly1305_ctx ctx;
    chacha_poly1305_set_key(&ctx, key);
    chacha_poly1305_set_nonce(&ctx, nonce);
    chacha_poly1305_update(&ctx, 32, aad);
    chacha_poly1305_encrypt(&ctx, n, ct, pt);
    chacha_poly1305_digest(&ctx, 16, tag);
    printf("tag %02x%02x\n", tag[0], tag[1]);

    int iters = 5;
    double t0 = now();
    for (int i = 0; i < iters; i++) {
        chacha_poly1305_set_key(&ctx, key);
        chacha_poly1305_set_nonce(&ctx, nonce);
        chacha_poly1305_update(&ctx, 32, aad);
        chacha_poly1305_encrypt(&ctx, n, ct, pt);
        chacha_poly1305_digest(&ctx, 16, tag);
    }
    double dt = now() - t0;
    printf("nettle aead %.2f ms  %.2f GB/s\n", dt/iters*1000, n/(dt/iters)/1e9);

