#include <stdint.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define ROTL(x, n) _mm256_or_si256(_mm256_slli_epi32((x), (n)), _mm256_srli_epi32((x), 32-(n)))

/* 8-way vertical ChaCha20, store transposed via extract */
static void chacha20_xor8(uint8_t *out, const uint8_t *in,
                          const uint32_t k[8], const uint32_t n[3], uint32_t ctr) {
    const __m256i rot8 = _mm256_set_epi8(
        14,13,12,15, 10,9,8,11, 6,5,4,7, 2,1,0,3,
        14,13,12,15, 10,9,8,11, 6,5,4,7, 2,1,0,3);
    const __m256i rot16 = _mm256_set_epi8(
        13,12,15,14, 9,8,11,10, 5,4,7,6, 1,0,3,2,
        13,12,15,14, 9,8,11,10, 5,4,7,6, 1,0,3,2);

    __m256i x0 = _mm256_set1_epi32(0x61707865);
    __m256i x1 = _mm256_set1_epi32(0x3320646e);
    __m256i x2 = _mm256_set1_epi32(0x79622d32);
    __m256i x3 = _mm256_set1_epi32(0x6b206574);
    __m256i x4 = _mm256_set1_epi32(k[0]);
    __m256i x5 = _mm256_set1_epi32(k[1]);
    __m256i x6 = _mm256_set1_epi32(k[2]);
    __m256i x7 = _mm256_set1_epi32(k[3]);
    __m256i x8 = _mm256_set1_epi32(k[4]);
    __m256i x9 = _mm256_set1_epi32(k[5]);
    __m256i x10= _mm256_set1_epi32(k[6]);
    __m256i x11= _mm256_set1_epi32(k[7]);
    __m256i x12= _mm256_set_epi32(ctr+7,ctr+6,ctr+5,ctr+4,ctr+3,ctr+2,ctr+1,ctr);
    __m256i x13= _mm256_set1_epi32(n[0]);
    __m256i x14= _mm256_set1_epi32(n[1]);
    __m256i x15= _mm256_set1_epi32(n[2]);

    __m256i s0=x0,s1=x1,s2=x2,s3=x3,s4=x4,s5=x5,s6=x6,s7=x7;
    __m256i s8=x8,s9=x9,s10=x10,s11=x11,s12=x12,s13=x13,s14=x14,s15=x15;

    #pragma unroll
    for (int i = 0; i < 10; i++) {
        s0 = _mm256_add_epi32(s0, s4); s12 = _mm256_xor_si256(s12, s0); s12 = _mm256_shuffle_epi8(s12, rot16);
        s1 = _mm256_add_epi32(s1, s5); s13 = _mm256_xor_si256(s13, s1); s13 = _mm256_shuffle_epi8(s13, rot16);
        s2 = _mm256_add_epi32(s2, s6); s14 = _mm256_xor_si256(s14, s2); s14 = _mm256_shuffle_epi8(s14, rot16);
        s3 = _mm256_add_epi32(s3, s7); s15 = _mm256_xor_si256(s15, s3); s15 = _mm256_shuffle_epi8(s15, rot16);

        s8 = _mm256_add_epi32(s8, s12); s4 = _mm256_xor_si256(s4, s8); s4 = ROTL(s4, 12);
        s9 = _mm256_add_epi32(s9, s13); s5 = _mm256_xor_si256(s5, s9); s5 = ROTL(s5, 12);
        s10= _mm256_add_epi32(s10,s14); s6 = _mm256_xor_si256(s6, s10); s6 = ROTL(s6, 12);
        s11= _mm256_add_epi32(s11,s15); s7 = _mm256_xor_si256(s7, s11); s7 = ROTL(s7, 12);

        s0 = _mm256_add_epi32(s0, s4); s12 = _mm256_xor_si256(s12, s0); s12 = _mm256_shuffle_epi8(s12, rot8);
        s1 = _mm256_add_epi32(s1, s5); s13 = _mm256_xor_si256(s13, s1); s13 = _mm256_shuffle_epi8(s13, rot8);
        s2 = _mm256_add_epi32(s2, s6); s14 = _mm256_xor_si256(s14, s2); s14 = _mm256_shuffle_epi8(s14, rot8);
        s3 = _mm256_add_epi32(s3, s7); s15 = _mm256_xor_si256(s15, s3); s15 = _mm256_shuffle_epi8(s15, rot8);

        s8 = _mm256_add_epi32(s8, s12); s4 = _mm256_xor_si256(s4, s8); s4 = ROTL(s4, 7);
        s9 = _mm256_add_epi32(s9, s13); s5 = _mm256_xor_si256(s5, s9); s5 = ROTL(s5, 7);
        s10= _mm256_add_epi32(s10,s14); s6 = _mm256_xor_si256(s6, s10); s6 = ROTL(s6, 7);
        s11= _mm256_add_epi32(s11,s15); s7 = _mm256_xor_si256(s7, s11); s7 = ROTL(s7, 7);

        /* diagonal: each lane independent, just permute word indices */
        s0 = _mm256_add_epi32(s0, s5); s15 = _mm256_xor_si256(s15, s0); s15 = _mm256_shuffle_epi8(s15, rot16);
        s1 = _mm256_add_epi32(s1, s6); s12 = _mm256_xor_si256(s12, s1); s12 = _mm256_shuffle_epi8(s12, rot16);
        s2 = _mm256_add_epi32(s2, s7); s13 = _mm256_xor_si256(s13, s2); s13 = _mm256_shuffle_epi8(s13, rot16);
        s3 = _mm256_add_epi32(s3, s4); s14 = _mm256_xor_si256(s14, s3); s14 = _mm256_shuffle_epi8(s14, rot16);

        s10= _mm256_add_epi32(s10,s15); s5 = _mm256_xor_si256(s5, s10); s5 = ROTL(s5, 12);
        s11= _mm256_add_epi32(s11,s12); s6 = _mm256_xor_si256(s6, s11); s6 = ROTL(s6, 12);
        s8 = _mm256_add_epi32(s8, s13); s7 = _mm256_xor_si256(s7, s8); s7 = ROTL(s7, 12);
        s9 = _mm256_add_epi32(s9, s14); s4 = _mm256_xor_si256(s4, s9); s4 = ROTL(s4, 12);

        s0 = _mm256_add_epi32(s0, s5); s15 = _mm256_xor_si256(s15, s0); s15 = _mm256_shuffle_epi8(s15, rot8);
        s1 = _mm256_add_epi32(s1, s6); s12 = _mm256_xor_si256(s12, s1); s12 = _mm256_shuffle_epi8(s12, rot8);
        s2 = _mm256_add_epi32(s2, s7); s13 = _mm256_xor_si256(s13, s2); s13 = _mm256_shuffle_epi8(s13, rot8);
        s3 = _mm256_add_epi32(s3, s4); s14 = _mm256_xor_si256(s14, s3); s14 = _mm256_shuffle_epi8(s14, rot8);

        s10= _mm256_add_epi32(s10,s15); s5 = _mm256_xor_si256(s5, s10); s5 = ROTL(s5, 7);
        s11= _mm256_add_epi32(s11,s12); s6 = _mm256_xor_si256(s6, s11); s6 = ROTL(s6, 7);
        s8 = _mm256_add_epi32(s8, s13); s7 = _mm256_xor_si256(s7, s8); s7 = ROTL(s7, 7);
        s9 = _mm256_add_epi32(s9, s14); s4 = _mm256_xor_si256(s4, s9); s4 = ROTL(s4, 7);
    }

    s0 = _mm256_add_epi32(s0, x0);
    s1 = _mm256_add_epi32(s1, x1);
    s2 = _mm256_add_epi32(s2, x2);
    s3 = _mm256_add_epi32(s3, x3);
    s4 = _mm256_add_epi32(s4, x4);
    s5 = _mm256_add_epi32(s5, x5);
    s6 = _mm256_add_epi32(s6, x6);
    s7 = _mm256_add_epi32(s7, x7);
    s8 = _mm256_add_epi32(s8, x8);
    s9 = _mm256_add_epi32(s9, x9);
    s10= _mm256_add_epi32(s10,x10);
    s11= _mm256_add_epi32(s11,x11);
    s12= _mm256_add_epi32(s12,x12);
    s13= _mm256_add_epi32(s13,x13);
    s14= _mm256_add_epi32(s14,x14);
    s15= _mm256_add_epi32(s15,x15);

    /* transpose 8x16 matrix of 32-bit words into 8 sequential 64-byte blocks.
       Use extract lanes. */
    __m256i rows[16] = {s0,s1,s2,s3,s4,s5,s6,s7,s8,s9,s10,s11,s12,s13,s14,s15};
    uint32_t tmp[16*8];
    for (int w = 0; w < 16; w++)
        _mm256_storeu_si256((__m256i*)(tmp + w*8), rows[w]);

    for (int b = 0; b < 8; b++) {
        uint32_t blk[16];
        for (int w = 0; w < 16; w++) blk[w] = tmp[w*8 + b];
        const uint8_t *src = in + b*64;
        uint8_t *dst = out + b*64;
        const uint8_t *ks = (const uint8_t*)blk;
        for (int i = 0; i < 64; i += 8) {
            uint64_t a, c;
            memcpy(&a, ks+i, 8);
            memcpy(&c, src+i, 8);
            a ^= c;
            memcpy(dst+i, &a, 8);
        }
    }
}

static void chacha_crypt(uint8_t *out, const uint8_t *in, size_t len,
                         const uint8_t key[32], const uint8_t nonce[12], uint32_t counter) {
    uint32_t k[8], n[3];
    memcpy(k, key, 32);
    memcpy(n, nonce, 12);
    size_t off = 0;
    while (off + 512 <= len) {
        chacha20_xor8(out+off, in+off, k, n, counter + (uint32_t)(off/64));
        off += 512;
    }
}

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

int main() {
    size_t n = 40000ull*1024;
    n -= n % 512;
    uint8_t *buf = aligned_alloc(64, n);
    uint8_t *out = aligned_alloc(64, n);
    memset(buf, 1, n);
    uint8_t key[32], nonce[12];
    for (int i=0;i<32;i++) key[i]=i;
    for (int i=0;i<12;i++) nonce[i]=i+1;
    chacha_crypt(out, buf, n, key, nonce, 1);
    int iters=5;
    double t0=now();
    for(int i=0;i<iters;i++) chacha_crypt(out, buf, n, key, nonce, 1);
    double dt=now()-t0;
    printf("unroll8 %.2f ms  %.2f GB/s  checksum %u\n", dt/iters*1000, n/(dt/iters)/1e9, out[0]);
    return 0;
}
EOF
