{"command":"python3 - << 'PY'
import os, time, threading
from cryptography.hazmat.primitives.ciphers.aead import ChaCha20Poly1305

n = 40*1024*1024
key = os.urandom(32)
nonce = os.urandom(12)
pt = os.urandom(n)
chs = [ChaCha20Poly1305(key) for _ in range(12)]

def bench(nthreads):
    chunk = n // nthreads
    chunks = [pt[i*chunk:(i+1)*chunk] for i in range(nthreads)]
    barrier = threading.Barrier(nthreads)
    def run(i):
        barrier.wait()
        return chs[i].encrypt(nonce, chunks[i], b"")
    threads = [threading.Thread(target=run, args=(i,)) for i in range(nthreads)]
    t0 = time.perf_counter()
    for t in threads: t.start()
    for t in threads: t.join()
    return (time.perf_counter()-t0)*1000

for nt in (1,2,4,6,8,12):
    for _ in range(2):
        bench(nt)
    times = [bench(nt) for _ in range(5)]
    print(f"threads={nt:2d} best={min(times):.1f} med={sorted(times)[2]:.1f} all={['%.1f'%t for t in times]}")
