{"command":"# C threads calling OpenSSL EVP directly, 4-way split of 40MB
cat > thr_bench.c << 'EOF'
#include <openssl/evp.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

typedef struct {
    uint8_t *in, *out;
    size_t n;
    uint8_t key[32];
    uint8_t nonce[12];
    pthread_barrier_t *bar;
} job_t;

static void *work(void *arg) {
    job_t *j = arg;
    pthread_barrier_wait(j->bar);
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_chacha20_poly1305(), NULL, NULL, NULL);
    int ivlen = 12;
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, ivlen, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, j->key, j->nonce);
    int outl = 0;
    EVP_EncryptUpdate(ctx, j->out, &outl, j->in, (int)j->n);
    int fin = 0;
    uint8_t extra[16];
    EVP_EncryptFinal_ex(ctx, extra, &fin);
    uint8_t tag[16];
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

int main() {
    size_t n = 40000ull*1024;
    int threads = 4;
    uint8_t *in = malloc(n);
    uint8_t *out = malloc(n+64);
    memset(in, 1, n);
    uint8_t key[32]={1}, nonce[12]={2};
    pthread_barrier_t bar;
    pthread_barrier_init(&bar, NULL, threads);
    pthread_t th[16];
    job_t jobs[16];
    size_t chunk = n / threads;
    for (int i = 0; i < threads; i++) {
        jobs[i].in = in + i*chunk;
        jobs[i].out = out + i*chunk;
        jobs[i].n = chunk;
        memcpy(jobs[i].key, key, 32);
        memcpy(jobs[i].nonce, nonce, 12);
        jobs[i].bar = &bar;
    }
    /* warmup */
    for (int i = 0; i < threads; i++) pthread_create(&th[i], NULL, work, &jobs[i]);
    for (int i = 0; i < threads; i++) pthread_join(th[i], NULL);

    int iters = 5;
    double t0 = now();
    for (int it = 0; it < iters; it++) {
        pthread_barrier_destroy(&bar);
        pthread_barrier_init(&bar, NULL, threads);
        for (int i = 0; i < threads; i++) pthread_create(&th[i], NULL, work, &jobs[i]);
        for (int i = 0; i < threads; i++) pthread_join(th[i], NULL);
    }
    double dt = now()-t0;
    printf("%d threads %.2f ms  %.2f GB/s\n", threads, dt/iters*1000, n/(dt/iters)/1e9);
    return 0;
}
EOF
