#define MAX_T 12
static int NTHREADS = 6;

typedef struct {
    uint8_t *out, *in;
    size_t n;
    unsigned int key[8];
    unsigned int counter[4];
    atomic_int *go;
    atomic_int *done;
    int id;
    int stop;
} worker_t;

static worker_t workers[MAX_T];
static pthread_t threads[MAX_T];

static void *worker_fn(void *arg) {
    worker_t *w = arg;
    int seen = 0;
    while (!w->stop) {
        while (atomic_load(w->go) == seen) {
            /* spin */
        }
        seen = atomic_load(w->go);
        if (w->stop) break;
        ChaCha20_ctr32(w->out, w->in, w->n, w->key, w->counter);
        atomic_fetch_add(w->done, 1);
    }
    return NULL;
}

static atomic_int go_flag, done_flag;

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

static void start_workers(int nt) {
    atomic_store(&go_flag, 0);
    atomic_store(&done_flag, 0);
    for (int i = 0; i < nt; i++) {
        workers[i].go = &go_flag;
        workers[i].done = &done_flag;
        workers[i].id = i;
        workers[i].stop = 0;
        pthread_create(&threads[i], NULL, worker_fn, &workers[i]);
    }
}

int main(int argc, char **argv) {
    int nt = argc > 1 ? atoi(argv[1]) : 6;
    size_t n = 40000ull * 1024;
    /* round down to 64 */
    n -= n % 64;
    uint8_t *in = aligned_alloc(64, n);
    uint8_t *out = aligned_alloc(64, n);
    memset(in, 1, n);
    unsigned int key[8] = {1,2,3,4,5,6,7,8};
    unsigned int counter[4] = {1, 0x11223344, 0x55667788, 0x99aabbcc};

    start_workers(nt);
    size_t chunk = (n / nt) & ~63ull;
    /* warmup */
    atomic_store(&done_flag, 0);
    for (int i = 0; i < nt; i++) {
        size_t off = i * chunk;
        size_t len = (i == nt-1) ? n - off : chunk;
        workers[i].out = out + off;
        workers[i].in = in + off;
        workers[i].n = len;
        memcpy(workers[i].key, key, 32);
        memcpy(workers[i].counter, counter, 16);
        workers[i].counter[0] = counter[0] + (unsigned)(off / 64);
    }
    atomic_fetch_add(&go_flag, 1);
    while (atomic_load(&done_flag) < nt) {}

    int iters = 8;
    double t0 = now();
    for (int it = 0; it < iters; it++) {
        atomic_store(&done_flag, 0);
        atomic_fetch_add(&go_flag, 1);
        while (atomic_load(&done_flag) < nt) {}
    }
    double dt = now() - t0;
    printf("chacha %d threads %.2f ms  %.2f GB/s\n", nt, dt/iters*1000, n/(dt/iters)/1e9);

    /* poly serial */
    size_t cs = Poly1305_ctx_size();
    void *ctx = malloc(cs);
    uint8_t pkey[32] = {0};
    uint8_t mac[16];
    t0 = now();
    for (int it = 0; it < iters; it++) {
        Poly1305_Init(ctx, pkey);
        Poly1305_Update(ctx, out, n);
        Poly1305_Final(ctx, mac);
    }
    dt = now() - t0;
    printf("poly serial %.2f ms  %.2f GB/s\n", dt/iters*1000, n/(dt/iters)/1e9);

    for (int i = 0; i < nt; i++) workers[i].stop = 1;
    atomic_fetch_add(&go_flag, 1);
    for (int i = 0; i < nt; i++) pthread_join(threads[i], NULL);
    printf("mac0 %02x\n", mac[0]);
    return 0;
}
